mapper.sql:
FROM t_user u LEFT JOIN ( SELECT t.user_openid, SUM(t.amt) AS consume_amount, MAX(t.pay_time) AS last_consume_time FROM ( SELECT TRIM(o.openid) AS user_openid, o.pay_time, (IFNULL(o.sett_amount, 0) - IFNULL(o.discount_amount, 0) + IFNULL(o.service_fee, 0) - IFNULL(o.refund_amount, 0) - IFNULL(o.pay_amount_gift, 0)) AS amt FROM t_order o WHERE o.transac_status = 'success' AND o.openid IS NOT NULL AND TRIM(o.openid) <> ''
UNION ALL SELECT TRIM(o.pay_openid) AS user_openid, o.pay_time, (IFNULL(o.sett_amount, 0) - IFNULL(o.discount_amount, 0) + IFNULL(o.service_fee, 0) - IFNULL(o.refund_amount, 0) - IFNULL(o.pay_amount_gift, 0)) AS amt FROM t_order o WHERE o.transac_status = 'success' AND o.pay_openid IS NOT NULL AND TRIM(o.pay_openid) <> '' AND (o.openid IS NULL OR TRIM(o.openid) = '' OR TRIM(o.openid) <> TRIM(o.pay_openid))
) t GROUP BY t.user_openid ) pay ON pay.user_openid = TRIM(u.openid)

